read_ic_types.h:
/* Experimental per-final-read-site IC. No QuickJS-NG runtime code imported. */
#include "read_ic_config.h"
#if RDI_CAPACITY == 1
typedef struct ReadICSite {
    JSShape *shape;
    uint32_t prop_offset;
    JSAtom atom;
} ReadICSite;
#elif RDI_CAPACITY == 4
typedef struct ReadICSite {
    JSShape *shape[4];
    uint32_t prop_offset[4];
    JSAtom atom;
    uint8_t recent, victim;
} ReadICSite;
#else
#error unsupported read IC capacity
#endif
typedef struct RDIFunctionDiag RDIFunctionDiag;
#ifdef READ_IC_DIAGNOSTIC
#define RDI_DPARAM , RDICounters *d
#define RDI_DARG(x) , (x)
#define RDI_COUNT(field) (++d->field)
#define RDI_REASON(field) (++d->field)
#define RDI_DLOCAL(index) RDICounters *d = &b->read_ic_diag->sites[index]
#define RDI_QUERY() rdi_diag_query(d)
#define RDI_OCCUPY() rdi_diag_occupy(d)
#define RDI_REPLACE() (++rdi_diag_shape_unref, ++rdi_diag_shape_ref, ++d->replacements)
#else
#define RDI_DPARAM
#define RDI_DARG(x)
#define RDI_COUNT(field) ((void)0)
#define RDI_REASON(field) ((void)0)
#define RDI_DLOCAL(index)
#define RDI_QUERY() ((void)0)
#define RDI_OCCUPY() ((void)0)
#define RDI_REPLACE() ((void)0)
#endif

read_ic_runtime.inc:
/* Included after upstream find_own_property, with shape helpers available. */
#ifdef READ_IC_DIAGNOSTIC
#include "read_ic_diag.h"
#endif
static force_inline uint32_t rdi_probe(ReadICSite *s, JSShape *shape RDI_DPARAM)
{
#if RDI_CAPACITY == 1
    RDI_COUNT(comparisons);
    if (s->shape == shape)
        return s->prop_offset;
#else
    unsigned i, first = s->recent;
    RDI_COUNT(comparisons);
    if (s->shape[first] == shape)
        return s->prop_offset[first];
    for (unsigned k = 1; k < 4; k++) {
        i = (first + k) & 3;
        RDI_COUNT(comparisons);
        if (s->shape[i] == shape) {
            s->recent = i;
            return s->prop_offset[i];
        }
    }
#endif
    return UINT32_MAX;
}
static force_inline void rdi_update(JSContext *ctx, ReadICSite *s,
                                    JSShape *shape, uint32_t offset RDI_DPARAM)
{
    RDI_COUNT(updates);
#if RDI_CAPACITY == 1
    if (s->shape == shape) {
        s->prop_offset = offset;
        return;
    }
    if (s->shape) { RDI_REPLACE(); } else { RDI_OCCUPY(); }
    js_dup_shape(shape);
    js_free_shape_null(ctx->rt, s->shape);
    s->shape = shape;
    s->prop_offset = offset;
#else
    unsigned i, empty = 4;
    for (i = 0; i < 4; i++) {
        RDI_COUNT(update_comparisons);
        if (s->shape[i] == shape) {
            s->prop_offset[i] = offset;
            s->recent = i;
            return;
        }
        if (!s->shape[i] && empty == 4)
            empty = i;
    }
    if (empty < 4) {
        i = empty;
        RDI_OCCUPY();
    } else {
        i = s->victim;
        s->victim = (i + 1) & 3;
        RDI_REPLACE();
    }
    js_dup_shape(shape);
    js_free_shape_null(ctx->rt, s->shape[i]);
    s->shape[i] = shape;
    s->prop_offset[i] = offset;
    s->recent = i;
#endif
}
static void rdi_free(JSRuntime *rt, JSFunctionBytecode *b)
{
    uint32_t i;
    for (i = 0; i < b->read_ic_count; i++) {
        ReadICSite *s = &b->read_ic_sites[i];
        JS_FreeAtomRT(rt, s->atom);
#if RDI_CAPACITY == 1
        js_free_shape_null(rt, s->shape);
#else
        for (unsigned j = 0; j < 4; j++)
            js_free_shape_null(rt, s->shape[j]);
#endif
    }
#ifdef READ_IC_DIAGNOSTIC
    rdi_diag_release(b);
#endif
    js_free_rt(rt, b->read_ic_sites);
    b->read_ic_sites = NULL;
    b->read_ic_count = 0;
}

read_ic_prepare.inc:
/* Called only for fully built b, after all compiler passes / atom fixups. */
static int rdi_prepare(JSContext *ctx, JSFunctionBytecode *b)
{
    uint32_t count = 0, index = 0;
    int pos, op;
    assert(!b->read_ic_ready && !b->read_ic_sites);
    b->read_ic_ready = 1;
#ifdef READ_IC_DIAGNOSTIC
    rdi_diag_header_init();
#endif
    for (pos = 0; pos < b->byte_code_len; pos += short_opcode_info(op).size) {
        op = b->byte_code_buf[pos];
        if (op == OP_get_field || op == OP_get_field2) count++;
    }
    if (!count) return 0;
    if (count > SIZE_MAX / sizeof(ReadICSite)) {
        JS_ThrowOutOfMemory(ctx);
        return -1;
    }
    b->read_ic_sites = js_mallocz(ctx, count * sizeof(ReadICSite));
    if (!b->read_ic_sites) return -1;
    b->read_ic_count = count;
#ifdef READ_IC_DIAGNOSTIC
    rdi_diag_prepare(ctx, b);
#endif
    for (pos = 0; pos < b->byte_code_len; pos += short_opcode_info(op).size) {
        uint8_t *pc = b->byte_code_buf + pos;
        op = *pc;
        if (op == OP_get_field || op == OP_get_field2) {
            b->read_ic_sites[index].atom = get_u32(pc + 1);
            *pc = (op == OP_get_field) ? OP_get_field_rdi : OP_get_field2_rdi;
            put_u32(pc + 1, index++);
        }
    }
    assert(index == count);
    return 0;
}
